/* @lc app=leetcode id=3615 lang=kotlin */ class Solution { fun maxLen(n: Int, edges: Array<IntArray>, label: String): Int = IntArray(n).also { adj -> edges.forEach { (a, b) -> adj[a] = adj[a] or (1 shl b) } }.also { adj -> edges.forEach { (a, b) -> adj[b] = adj[b] or (1 shl a) } }.let { adj -> BooleanArray((1 shl n) * n * n).let { vis -> IntArray((1 shl n) * n * n).let { q -> IntArray(2).let { c -> { mask: Int, u: Int, v: Int -> ((mask * n + minOf(u, v)) * n + maxOf(u, v)).let { s -> if (!vis[s]) vis.set(s, true).also { q[c[0]++] = s }.also { c[1] = maxOf(c[1], Integer.bitCount(mask)) } } }.let { push -> (0 until n).forEach { push(1 shl it, it, it) }.also { edges.forEach { (a, b) -> if (label[a] == label[b]) push((1 shl a) or (1 shl b), a, b) } }.let { generateSequence(0) { if (it + 1 < c[0]) it + 1 else null }.forEach { h -> q[h].let { s -> (s / (n * n)).let { mask -> (s / n % n).let { u -> (s % n).let { v -> (adj[u] and mask.inv()).let { A -> (adj[v] and mask.inv()).let { B -> (0 until n).forEach { a -> if (A shr a and 1 == 1) (0 until n).forEach { b -> if (b != a && B shr b and 1 == 1 && label[a] == label[b]) push(mask or (1 shl a) or (1 shl b), a, b) } } } } } } } } }.let { c[1] } } } } } } } }